/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["adm"]=g.BC_LEI_REVISAO["adm"]||{};g.BC_LEI_REVISAO["adm"][14]=[{"key":"cf:37","law":"cf","ref":"37","label":"Constituição Federal · CF/88 · Art. 37","paragraphs":["Art. 37. A administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência e, também, ao seguinte: (“Caput” do artigo com redação dada pela Emenda Constitucional nº 19, de 1998)","I - os cargos, empregos e funções públicas são acessíveis aos brasileiros que preencham os requisitos estabelecidos em lei, assim como aos estrangeiros, na forma da lei; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","II - a investidura em cargo ou emprego público depende de aprovação prévia em concurso público de provas ou de provas e títulos, de acordo com a natureza e a complexidade do cargo ou emprego, na forma prevista em lei, ressalvadas as nomeações para cargo em comissão declarado em lei de livre nomeação e exoneração; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","III - o prazo de validade do concurso público será de até dois anos, prorrogável uma vez, por igual período;","IV - durante o prazo improrrogável previsto no edital de convocação, aquele aprovado em concurso público de provas ou de provas e títulos será convocado com prioridade sobre novos concursados para assumir cargo ou emprego, na carreira;","V - as funções de confiança, exercidas exclusivamente por servidores ocupantes de cargo efetivo, e os cargos em comissão, a serem preenchidos por servidores de carreira nos casos, condições e percentuais mínimos previstos em lei, destinam-se apenas às atribuições de direção, chefia e assessoramento; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VI - é garantido ao servidor público civil o direito à livre associação sindical;","VII - o direito de greve será exercido nos termos e nos limites definidos em lei específica; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VIII - a lei reservará percentual dos cargos e empregos públicos para as pessoas portadoras de deficiência e definirá os critérios de sua admissão;","IX - a lei estabelecerá os casos de contratação por tempo determinado para atender a necessidade temporária de excepcional interesse público;","X - a remuneração dos servidores públicos e o subsídio de que trata o § 4º do art. 39 somente poderão ser fixados ou alterados por lei específica, observada a iniciativa privativa em cada caso, assegurada revisão geral anual, sempre na mesma data e sem distinção de índices; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XI - a remuneração e o subsídio dos ocupantes de cargos, funções e empregos públicos da administração direta, autárquica e fundacional, dos membros de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios, dos detentores de mandato eletivo e dos demais agentes políticos e os proventos, pensões ou outra espécie remuneratória, percebidos cumulativamente ou não, incluídas as vantagens pessoais ou de qualquer outra natureza, não poderão exceder o subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, aplicando-se como limite, nos Municípios, o subsídio do Prefeito, e nos Estados e no Distrito Federal, o subsídio mensal do Governador no âmbito do Poder Executivo, o subsídio dos Deputados Estaduais e Distritais no âmbito do Poder Legislativo e o subsídio dos Desembargadores do Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, no âmbito do Poder Judiciário, aplicável este limite aos membros do Ministério Público, aos Procuradores e aos Defensores Públicos; (Inciso com redação dada pela Emenda Constitucional nº 41, de 2003)","XII - os vencimentos dos cargos do Poder Legislativo e do Poder Judiciário não poderão ser superiores aos pagos pelo Poder Executivo;","XIII - é vedada a vinculação ou equiparação de quaisquer espécies remuneratórias para o efeito de remuneração de pessoal do serviço público; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XIV - os acréscimos pecuniários percebidos por servidor público não serão computados nem acumulados para fins de concessão de acréscimos ulteriores; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XV - o subsídio e os vencimentos dos ocupantes de cargos e empregos públicos são irredutíveis, ressalvado o disposto nos incisos XI e XIV deste artigo e nos arts. 39, § 4º, 150, II, 153, III, e 153, § 2º, I; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XVI - é vedada a acumulação remunerada de cargos públicos, exceto, quando houver compatibilidade de horários, observado em qualquer caso o disposto no inciso XI: (“Caput” do inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","a) a de dois cargos de professor;","b) a de um cargo de professor com outro de qualquer natureza; (Alínea com redação dada pela Emenda Constitucional nº 138, de 2025)","c) a de dois cargos ou empregos privativos de profissionais de saúde, com profissões regulamentadas; (Alínea com redação dada pela Emenda Constitucional nº 34, de 2001)","XVII - a proibição de acumular estende-se a empregos e funções e abrange autarquias, fundações, empresas públicas, sociedades de economia mista, suas subsidiárias, e sociedades controladas, direta ou indiretamente, pelo poder público; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XVIII - a administração fazendária e seus servidores fiscais terão, dentro de suas áreas de competência e jurisdição, precedência sobre os demais setores administrativos, na forma da lei;","XIX - somente por lei específica poderá ser criada autarquia e autorizada a instituição de empresa pública, de sociedade de economia mista e de fundação, cabendo à lei complementar, neste último caso, definir as áreas de sua atuação; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XX - depende de autorização legislativa, em cada caso, a criação de subsidiárias das entidades mencionadas no inciso anterior, assim como a participação de qualquer delas em empresa privada;","XXI - ressalvados os casos especificados na legislação, as obras, serviços, compras e alienações serão contratados mediante processo de licitação pública que assegure igualdade de condições a todos os concorrentes, com cláusulas que estabeleçam obrigações de pagamento, mantidas as condições efetivas da proposta, nos termos da lei, o qual somente permitirá as exigências de qualificação técnica e econômica indispensáveis à garantia do cumprimento das obrigações.","XXII - as administrações tributárias da União, dos Estados, do Distrito Federal e dos Municípios, atividades essenciais ao funcionamento do Estado, exercidas por servidores de carreiras específicas, terão recursos prioritários para a realização de suas atividades e atuarão de forma integrada, inclusive com o compartilhamento de cadastros e de informações fiscais, na forma da lei ou convênio. (Inciso acrescido pela Emenda Constitucional nº 42, de 2003)","§ 1º A publicidade dos atos, programas, obras, serviços e campanhas dos órgãos públicos deverá ter caráter educativo, informativo ou de orientação social, dela não podendo constar nomes, símbolos ou imagens que caracterizem promoção pessoal de autoridades ou servidores públicos.","§ 2º A não-observância do disposto nos incisos II e III implicará a nulidade do ato e a punição da autoridade responsável, nos termos da lei.","§ 3º A lei disciplinará as formas de participação do usuário na administração pública direta e indireta, regulando especialmente:","I - as reclamações relativas à prestação dos serviços públicos em geral, asseguradas a manutenção de serviços de atendimento ao usuário e a avaliação periódica, externa e interna, da qualidade dos serviços;","II - o acesso dos usuários a registros administrativos e a informações sobre atos de governo, observado o disposto no art. 5º, X e XXXIII;","III - a disciplina da representação contra o exercício negligente ou abusivo de cargo, emprego ou função na administração pública. (Parágrafo com redação dada pela Emenda Constitucional nº 19, de 1998)","§ 4º Os atos de improbidade administrativa importarão a suspensão dos direitos políticos, a perda da função pública, a indisponibilidade dos bens e o ressarcimento ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.","§ 5º A lei estabelecerá os prazos de prescrição para ilícitos praticados por qualquer agente, servidor ou não, que causem prejuízos ao erário, ressalvadas as respectivas ações de ressarcimento.","§ 6º As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.","§ 7º A lei disporá sobre os requisitos e as restrições ao ocupante de cargo ou emprego da administração direta e indireta que possibilite o acesso a informações privilegiadas. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 8º A autonomia gerencial, orçamentária e financeira dos órgãos e entidades da administração direta e indireta poderá ser ampliada mediante contrato, a ser firmado entre seus administradores e o poder público, que tenha por objeto a fixação de metas de desempenho para o órgão ou entidade, cabendo à lei dispor sobre:","I - o prazo de duração do contrato;","II - os controles e critérios de avaliação de desempenho, direitos, obrigações e responsabilidade dos dirigentes;","III - a remuneração do pessoal. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 9º O disposto no inciso XI aplica-se às empresas públicas e às sociedades de economia mista, e suas subsidiárias, que receberem recursos da União, dos Estados, do Distrito Federal ou dos Municípios para pagamento de despesas de pessoal ou de custeio em geral. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 10. É vedada a percepção simultânea de proventos de aposentadoria decorrentes do art. 40 ou dos arts. 42 e 142 com a remuneração de cargo, emprego ou função pública, ressalvados os cargos acumuláveis na forma desta Constituição, os cargos eletivos e os cargos em comissão declarados em lei de livre nomeação e exoneração. (Parágrafo acrescido pela Emenda Constitucional nº 20, de 1998)","§ 11. Não serão computadas, para efeito dos limites remuneratórios de que trata o inciso XI do caput deste artigo, as parcelas de caráter indenizatório expressamente previstas em lei ordinária, aprovada pelo Congresso Nacional, de caráter nacional, aplicada a todos os Poderes e órgãos constitucionalmente autônomos. (Parágrafo acrescido pela Emenda Constitucional nº 47, de 2005, e com redação dada pela Emenda Constitucional nº 135, de 2024)","§ 12. Para os fins do disposto no inciso XI do caput deste artigo, fica facultado aos Estados e ao Distrito Federal fixar, em seu âmbito, mediante emenda às respectivas Constituições e Lei Orgânica, como limite único, o subsídio mensal dos Desembargadores do respectivo Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal dos Ministros do Supremo Tribunal Federal, não se aplicando o disposto neste parágrafo aos subsídios dos Deputados Estaduais e Distritais e dos Vereadores. (Parágrafo acrescido pela Emenda Constitucional nº 47, de 2005)","§ 13. O servidor público titular de cargo efetivo poderá ser readaptado para exercício de cargo cujas atribuições e responsabilidades sejam compatíveis com a limitação que tenha sofrido em sua capacidade física ou mental, enquanto permanecer nesta condição, desde que possua a habilitação e o nível de escolaridade exigidos para o cargo de destino, mantida a remuneração do cargo de origem. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 14. A aposentadoria concedida com a utilização de tempo de contribuição decorrente de cargo, emprego ou função pública, inclusive do Regime Geral de Previdência Social, acarretará o rompimento do vínculo que gerou o referido tempo de contribuição. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 15. É vedada a complementação de aposentadorias de servidores públicos e de pensões por morte a seus dependentes que não seja decorrente do disposto nos §§ 14 a 16 do art. 40 ou que não seja prevista em lei que extinga regime próprio de previdência social. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 16. Os órgãos e entidades da administração pública, individual ou conjuntamente, devem realizar avaliação das políticas públicas, inclusive com divulgação do objeto a ser avaliado e dos resultados alcançados, na forma da lei. (Parágrafo acrescido pela Emenda Constitucional nº 109, de 2021)","§ 17. (Vide Emenda Constitucional nº 132, de 2023)","§ 18. (Vide Emenda Constitucional nº 132, de 2023)"],"url":""},{"key":"cf:22","law":"cf","ref":"22","label":"Constituição Federal · CF/88 · Art. 22","paragraphs":["Art. 22. Compete privativamente à União legislar sobre:","I - direito civil, comercial, penal, processual, eleitoral, agrário, marítimo, aeronáutico, espacial e do trabalho;","II - desapropriação;","III - requisições civis e militares, em caso de iminente perigo e em tempo de guerra;","IV - águas, energia, informática, telecomunicações e radiodifusão;","V - serviço postal;","VI - sistema monetário e de medidas, títulos e garantias dos metais;","VII - política de crédito, câmbio, seguros e transferência de valores;","VIII - comércio exterior e interestadual;","IX - diretrizes da política nacional de transportes;","X - regime dos portos, navegação lacustre, fluvial, marítima, aérea e aeroespacial;","XI - trânsito e transporte;","XII - jazidas, minas, outros recursos minerais e metalurgia;","XIII - nacionalidade, cidadania e naturalização;","XIV - populações indígenas;","XV - emigração e imigração, entrada, extradição e expulsão de estrangeiros;","XVI - organização do sistema nacional de emprego e condições para o exercício de profissões;","XVII - organização judiciária, do Ministério Público do Distrito Federal e dos Territórios e da Defensoria Pública dos Territórios, bem como organização administrativa destes; (Inciso com redação dada pela Emenda Constitucional nº 69, de 2012, publicada no DOU de 30/3/2012, produzindo efeitos 120 dias após a publicação)","XVIII - sistema estatístico, sistema cartográfico e de geologia nacionais;","XIX - sistemas de poupança, captação e garantia da poupança popular;","XX - sistemas de consórcios e sorteios;","XXI - normas gerais de organização, efetivos, material bélico, garantias, convocação, mobilização, inatividades e pensões das polícias militares e dos corpos de bombeiros militares; (Inciso com redação dada pela Emenda Constitucional nº 103, de 2019)","XXII - competência da polícia federal e das polícias rodoviária e ferroviária federais;","XXIII - seguridade social;","XXIV - diretrizes e bases da educação nacional;","XXV - registros públicos;","XXVI - atividades nucleares de qualquer natureza;","XXVII - normas gerais de licitação e contratação, em todas as modalidades, para as administrações públicas diretas, autárquicas e fundacionais da União, Estados, Distrito Federal e Municípios, obedecido o disposto no art. 37, XXI, e para as empresas públicas e sociedades de economia mista, nos termos do art. 173, § 1º, III; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XXVIII - defesa territorial, defesa aeroespacial, defesa marítima, defesa civil e mobilização nacional;","XXIX - propaganda comercial.","XXX - proteção e tratamento de dados pessoais. (Inciso acrescido pela Emenda Constitucional nº 115, de 2022)","Parágrafo único. Lei complementar poderá autorizar os Estados a legislar sobre questões específicas das matérias relacionadas neste artigo."],"url":""},{"key":"l14133:11","law":"l14133","ref":"11","label":"Nova Lei de Licitações e Contratos · Art. 11","paragraphs":["Art. 11. O processo licitatório tem por objetivos:","I - assegurar a seleção da proposta apta a gerar o resultado de contratação mais vantajoso para a Administração Pública, inclusive no que se refere ao ciclo de vida do objeto;","II - assegurar tratamento isonômico entre os licitantes, bem como a justa competição;","III - evitar contratações com sobrepreço ou com preços manifestamente inexequíveis e superfaturamento na execução dos contratos;","IV - incentivar a inovação e o desenvolvimento nacional sustentável.","Parágrafo único. A alta administração do órgão ou entidade é responsável pela governança das contratações e deve implementar processos e estruturas, inclusive de gestão de riscos e controles internos, para avaliar, direcionar e monitorar os processos licitatórios e os respectivos contratos, com o intuito de alcançar os objetivos estabelecidos no caput deste artigo, promover um ambiente íntegro e confiável, assegurar o alinhamento das contratações ao planejamento estratégico e às leis orçamentárias e promover eficiência, efetividade e eficácia em suas contratações."],"url":""},{"key":"l14133:5","law":"l14133","ref":"5","label":"Nova Lei de Licitações e Contratos · Art. 5","paragraphs":["Art. 5º Na aplicação desta Lei, serão observados os princípios da legalidade, da impessoalidade, da moralidade, da publicidade, da eficiência, do interesse público, da probidade administrativa, da igualdade, do planejamento, da transparência, da eficácia, da segregação de funções, da motivação, da vinculação ao edital, do julgamento objetivo, da segurança jurídica, da razoabilidade, da competitividade, da proporcionalidade, da celeridade, da economicidade e do desenvolvimento nacional sustentável, assim como as disposições do Decreto-Lei nº 4.657, de 4 de setembro de 1942 (Lei de Introdução às Normas do Direito Brasileiro)."],"url":""},{"key":"l14133:1","law":"l14133","ref":"1","label":"Nova Lei de Licitações e Contratos · Art. 1","paragraphs":["Art. 1º Esta Lei estabelece normas gerais de licitação e contratação para as Administrações Públicas diretas, autárquicas e fundacionais da União, dos Estados, do Distrito Federal e dos Municípios, e abrange:","I - os órgãos dos Poderes Legislativo e Judiciário da União, dos Estados e do Distrito Federal e os órgãos do Poder Legislativo dos Municípios, quando no desempenho de função administrativa;","II - os fundos especiais e as demais entidades controladas direta ou indiretamente pela Administração Pública.","§ 1º Não são abrangidas por esta Lei as empresas públicas, as sociedades de economia mista e as suas subsidiárias, regidas pela Lei nº 13.303, de 30 de junho de 2016, ressalvado o disposto no art. 178 desta Lei.","§ 2º As contratações realizadas no âmbito das repartições públicas sediadas no exterior obedecerão às peculiaridades locais e aos princípios básicos estabelecidos nesta Lei, na forma de regulamentação específica a ser editada por ministro de Estado.","§ 3º Nas licitações e contratações que envolvam recursos provenientes de empréstimo ou doação oriundos de agência oficial de cooperação estrangeira ou de organismo financeiro de que o Brasil seja parte, podem ser admitidas:","I - condições decorrentes de acordos internacionais aprovados pelo Congresso Nacional e ratificados pelo Presidente da República;","II - condições peculiares à seleção e à contratação constantes de normas e procedimentos das agências ou dos organismos, desde que:","a) sejam exigidas para a obtenção do empréstimo ou doação;","b) não conflitem com os princípios constitucionais em vigor;","c) sejam indicadas no respectivo contrato de empréstimo ou doação e tenham sido objeto de parecer favorável do órgão jurídico do contratante do financiamento previamente à celebração do referido contrato;","d) (VETADO).","§ 4º A documentação encaminhada ao Senado Federal para autorização do empréstimo de que trata o § 3º deste artigo deverá fazer referência às condições contratuais que incidam na hipótese do referido parágrafo.","§ 5º As contratações relativas à gestão, direta e indireta, das reservas internacionais do País, inclusive as de serviços conexos ou acessórios a essa atividade, serão disciplinadas em ato normativo próprio do Banco Central do Brasil, assegurada a observância dos princípios estabelecidos no caput do art. 37 da Constituição Federal."],"url":""},{"key":"l14133:2","law":"l14133","ref":"2","label":"Nova Lei de Licitações e Contratos · Art. 2","paragraphs":["Art. 2º Esta Lei aplica-se a:","I - alienação e concessão de direito real de uso de bens;","II - compra, inclusive por encomenda;","III - locação;","IV - concessão e permissão de uso de bens públicos;","V - prestação de serviços, inclusive os técnico-profissionais especializados;","VI - obras e serviços de arquitetura e engenharia;","VII - contratações de tecnologia da informação e de comunicação."],"url":""},{"key":"l14133:6","law":"l14133","ref":"6","label":"Nova Lei de Licitações e Contratos · Art. 6","paragraphs":["Art. 6º Para os fins desta Lei, consideram-se:","I - órgão: unidade de atuação integrante da estrutura da Administração Pública;","II - entidade: unidade de atuação dotada de personalidade jurídica;","III - Administração Pública: administração direta e indireta da União, dos Estados, do Distrito Federal e dos Municípios, inclusive as entidades com personalidade jurídica de direito privado sob controle do poder público e as fundações por ele instituídas ou mantidas;","IV - Administração: órgão ou entidade por meio do qual a Administração Pública atua;","V - agente público: indivíduo que, em virtude de eleição, nomeação, designação, contratação ou qualquer outra forma de investidura ou vínculo, exerce mandato, cargo, emprego ou função em pessoa jurídica integrante da Administração Pública;","VI - autoridade: agente público dotado de poder de decisão;","VII - contratante: pessoa jurídica integrante da Administração Pública responsável pela contratação;","VIII - contratado: pessoa física ou jurídica, ou consórcio de pessoas jurídicas, signatária de contrato com a Administração;","IX - licitante: pessoa física ou jurídica, ou consórcio de pessoas jurídicas, que participa ou manifesta a intenção de participar de processo licitatório, sendo-lhe equiparável, para os fins desta Lei, o fornecedor ou o prestador de serviço que, em atendimento à solicitação da Administração, oferece proposta;","X - compra: aquisição remunerada de bens para fornecimento de uma só vez ou parceladamente, considerada imediata aquela com prazo de entrega de até 30 (trinta) dias da ordem de fornecimento;","XI - serviço: atividade ou conjunto de atividades destinadas a obter determinada utilidade, intelectual ou material, de interesse da Administração;","XII - obra: toda atividade estabelecida, por força de lei, como privativa das profissões de arquiteto e engenheiro que implica intervenção no meio ambiente por meio de um conjunto harmônico de ações que, agregadas, formam um todo que inova o espaço físico da natureza ou acarreta alteração substancial das características originais de bem imóvel;","XIII - bens e serviços comuns: aqueles cujos padrões de desempenho e qualidade podem ser objetivamente definidos pelo edital, por meio de especificações usuais de mercado;","XIV - bens e serviços especiais: aqueles que, por sua alta heterogeneidade ou complexidade, não podem ser descritos na forma do inciso XIII do caput deste artigo, exigida justificativa prévia do contratante;","XV - serviços e fornecimentos contínuos: serviços contratados e compras realizadas pela Administração Pública para a manutenção da atividade administrativa, decorrentes de necessidades permanentes ou prolongadas;","XVI - serviços contínuos com regime de dedicação exclusiva de mão de obra: aqueles cujo modelo de execução contratual exige, entre outros requisitos, que:","a) os empregados do contratado fiquem à disposição nas dependências do contratante para a prestação dos serviços;","b) o contratado não compartilhe os recursos humanos e materiais disponíveis de uma contratação para execução simultânea de outros contratos;","c) o contratado possibilite a fiscalização pelo contratante quanto à distribuição, controle e supervisão dos recursos humanos alocados aos seus contratos;","XVII - serviços não contínuos ou contratados por escopo: aqueles que impõem ao contratado o dever de realizar a prestação de um serviço específico em período predeterminado, podendo ser prorrogado, desde que justificadamente, pelo prazo necessário à conclusão do objeto;","XVIII - serviços técnicos especializados de natureza predominantemente intelectual: aqueles realizados em trabalhos relativos a:","a) estudos técnicos, planejamentos, projetos básicos e projetos executivos;","b) pareceres, perícias e avaliações em geral;","c) assessorias e consultorias técnicas e auditorias financeiras e tributárias;","d) fiscalização, supervisão e gerenciamento de obras e serviços;","e) patrocínio ou defesa de causas judiciais e administrativas;","f) treinamento e aperfeiçoamento de pessoal;","g) restauração de obras de arte e de bens de valor histórico;","h) controles de qualidade e tecnológico, análises, testes e ensaios de campo e laboratoriais, instrumentação e monitoramento de parâmetros específicos de obras e do meio ambiente e demais serviços de engenharia que se enquadrem na definição deste inciso;","XIX - notória especialização: qualidade de profissional ou de empresa cujo conceito, no campo de sua especialidade, decorrente de desempenho anterior, estudos, experiência, publicações, organização, aparelhamento, equipe técnica ou outros requisitos relacionados com suas atividades, permite inferir que o seu trabalho é essencial e reconhecidamente adequado à plena satisfação do objeto do contrato;","XX - estudo técnico preliminar: documento constitutivo da primeira etapa do planejamento de uma contratação que caracteriza o interesse público envolvido e a sua melhor solução e dá base ao anteprojeto, ao termo de referência ou ao projeto básico a serem elaborados caso se conclua pela viabilidade da contratação;","XXI - serviço de engenharia: toda atividade ou conjunto de atividades destinadas a obter determinada utilidade, intelectual ou material, de interesse para a Administração e que, não enquadradas no conceito de obra a que se refere o inciso XII do caput deste artigo, são estabelecidas, por força de lei, como privativas das profissões de arquiteto e engenheiro ou de técnicos especializados, que compreendem:","a) serviço comum de engenharia: todo serviço de engenharia que tem por objeto ações, objetivamente padronizáveis em termos de desempenho e qualidade, de manutenção, de adequação e de adaptação de bens móveis e imóveis, com preservação das características originais dos bens;","b) serviço especial de engenharia: aquele que, por sua alta heterogeneidade ou complexidade, não pode se enquadrar na definição constante da alínea \"a\" deste inciso;","XXII - obras, serviços e fornecimentos de grande vulto: aqueles cujo valor estimado supera R$ 200.000.000,00 (duzentos milhões de reais); (Vide Decreto nº 12.807, de 29/12/2025)","XXIII - termo de referência: documento necessário para a contratação de bens e serviços, que deve conter os seguintes parâmetros e elementos descritivos:","a) definição do objeto, incluídos sua natureza, os quantitativos, o prazo do contrato e, se for o caso, a possibilidade de sua prorrogação;","b) fundamentação da contratação, que consiste na referência aos estudos técnicos preliminares correspondentes ou, quando não for possível divulgar esses estudos, no extrato das partes que não contiverem informações sigilosas;","c) descrição da solução como um todo, considerado todo o ciclo de vida do objeto;","d) requisitos da contratação;","e) modelo de execução do objeto, que consiste na definição de como o contrato deverá produzir os resultados pretendidos desde o seu início até o seu encerramento;","f) modelo de gestão do contrato, que descreve como a execução do objeto será acompanhada e fiscalizada pelo órgão ou entidade;","g) critérios de medição e de pagamento;","h) forma e critérios de seleção do fornecedor;","i) estimativas do valor da contratação, acompanhadas dos preços unitários referenciais, das memórias de cálculo e dos documentos que lhe dão suporte, com os parâmetros utilizados para a obtenção dos preços e para os respectivos cálculos, que devem constar de documento separado e classificado;","j) adequação orçamentária;","XXIV - anteprojeto: peça técnica com todos os subsídios necessários à elaboração do projeto básico, que deve conter, no mínimo, os seguintes elementos:","a) demonstração e justificativa do programa de necessidades, avaliação de demanda do público-alvo, motivação técnico-econômico-social do empreendimento, visão global dos investimentos e definições relacionadas ao nível de serviço desejado;","b) condições de solidez, de segurança e de durabilidade;","c) prazo de entrega;","d) estética do projeto arquitetônico, traçado geométrico e/ou projeto da área de influência, quando cabível;","e) parâmetros de adequação ao interesse público, de economia na utilização, de facilidade na execução, de impacto ambiental e de acessibilidade;","f) proposta de concepção da obra ou do serviço de engenharia;","g) projetos anteriores ou estudos preliminares que embasaram a concepção proposta;","h) levantamento topográfico e cadastral;","i) pareceres de sondagem;","j) memorial descritivo dos elementos da edificação, dos componentes construtivos e dos materiais de construção, de forma a estabelecer padrões mínimos para a contratação;","XXV - projeto básico: conjunto de elementos necessários e suficientes, com nível de precisão adequado para definir e dimensionar a obra ou o serviço, ou o complexo de obras ou de serviços objeto da licitação, elaborado com base nas indicações dos estudos técnicos preliminares, que assegure a viabilidade técnica e o adequado tratamento do impacto ambiental do empreendimento e que possibilite a avaliação do custo da obra e a definição dos métodos e do prazo de execução, devendo conter os seguintes elementos:","a) levantamentos topográficos e cadastrais, sondagens e ensaios geotécnicos, ensaios e análises laboratoriais, estudos socioambientais e demais dados e levantamentos necessários para execução da solução escolhida;","b) soluções técnicas globais e localizadas, suficientemente detalhadas, de forma a evitar, por ocasião da elaboração do projeto executivo e da realização das obras e montagem, a necessidade de reformulações ou variantes quanto à qualidade, ao preço e ao prazo inicialmente definidos;","c) identificação dos tipos de serviços a executar e dos materiais e equipamentos a incorporar à obra, bem como das suas especificações, de modo a assegurar os melhores resultados para o empreendimento e a segurança executiva na utilização do objeto, para os fins a que se destina, considerados os riscos e os perigos identificáveis, sem frustrar o caráter competitivo para a sua execução;","d) informações que possibilitem o estudo e a definição de métodos construtivos, de instalações provisórias e de condições organizacionais para a obra, sem frustrar o caráter competitivo para a sua execução;","e) subsídios para montagem do plano de licitação e gestão da obra, compreendidos a sua programação, a estratégia de suprimentos, as normas de fiscalização e outros dados necessários em cada caso;","f) orçamento detalhado do custo global da obra, fundamentado em quantitativos de serviços e fornecimentos propriamente avaliados, obrigatório exclusivamente para os regimes de execução previstos nos incisos I, II, III, IV e VII do caput do art. 46 desta Lei;","XXVI - projeto executivo: conjunto de elementos necessários e suficientes à execução completa da obra, com o detalhamento das soluções previstas no projeto básico, a identificação de serviços, de materiais e de equipamentos a serem incorporados à obra, bem como suas especificações técnicas, de acordo com as normas técnicas pertinentes;","XXVII - matriz de riscos: cláusula contratual definidora de riscos e de responsabilidades entre as partes e caracterizadora do equilíbrio econômico-financeiro inicial do contrato, em termos de ônus financeiro decorrente de eventos supervenientes à contratação, contendo, no mínimo, as seguintes informações:","a) listagem de possíveis eventos supervenientes à assinatura do contrato que possam causar impacto em seu equilíbrio econômico-financeiro e previsão de eventual necessidade de prolação de termo aditivo por ocasião de sua ocorrência;","b) no caso de obrigações de resultado, estabelecimento das frações do objeto com relação às quais haverá liberdade para os contratados inovarem em soluções metodológicas ou tecnológicas, em termos de modificação das soluções previamente delineadas no anteprojeto ou no projeto básico;","c) no caso de obrigações de meio, estabelecimento preciso das frações do objeto com relação às quais não haverá liberdade para os contratados inovarem em soluções metodológicas ou tecnológicas, devendo haver obrigação de aderência entre a execução e a solução predefinida no anteprojeto ou no projeto básico, consideradas as características do regime de execução no caso de obras e serviços de engenharia;","XXVIII - empreitada por preço unitário: contratação da execução da obra ou do serviço por preço certo de unidades determinadas;","XXIX - empreitada por preço global: contratação da execução da obra ou do serviço por preço certo e total;","XXX - empreitada integral: contratação de empreendimento em sua integralidade, compreendida a totalidade das etapas de obras, serviços e instalações necessárias, sob inteira responsabilidade do contratado até sua entrega ao contratante em condições de entrada em operação, com características adequadas às finalidades para as quais foi contratado e atendidos os requisitos técnicos e legais para sua utilização com segurança estrutural e operacional;","XXXI - contratação por tarefa: regime de contratação de mão de obra para pequenos trabalhos por preço certo, com ou sem fornecimento de materiais;","XXXII - contratação integrada: regime de contratação de obras e serviços de engenharia em que o contratado é responsável por elaborar e desenvolver os projetos básico e executivo, executar obras e serviços de engenharia, fornecer bens ou prestar serviços especiais e realizar montagem, teste, pré-operação e as demais operações necessárias e suficientes para a entrega final do objeto;","XXXIII - contratação semi-integrada: regime de contratação de obras e serviços de engenharia em que o contratado é responsável por elaborar e desenvolver o projeto executivo, executar obras e serviços de engenharia, fornecer bens ou prestar serviços especiais e realizar montagem, teste, pré-operação e as demais operações necessárias e suficientes para a entrega final do objeto;","XXXIV - fornecimento e prestação de serviço associado: regime de contratação em que, além do fornecimento do objeto, o contratado responsabiliza-se por sua operação, manutenção ou ambas, por tempo determinado;","XXXV - licitação internacional: licitação processada em território nacional na qual é admitida a participação de licitantes estrangeiros, com a possibilidade de cotação de preços em moeda estrangeira, ou licitação na qual o objeto contratual pode ou deve ser executado no todo ou em parte em território estrangeiro;","XXXVI - serviço nacional: serviço prestado em território nacional, nas condições estabelecidas pelo Poder Executivo federal;","XXXVII - produto manufaturado nacional: produto manufaturado produzido no território nacional de acordo com o processo produtivo básico ou com as regras de origem estabelecidas pelo Poder Executivo federal;","XXXVIII - concorrência: modalidade de licitação para contratação de bens e serviços especiais e de obras e serviços comuns e especiais de engenharia, cujo critério de julgamento poderá ser:","a) menor preço;","b) melhor técnica ou conteúdo artístico;","c) técnica e preço;","d) maior retorno econômico;","e) maior desconto;","XXXIX - concurso: modalidade de licitação para escolha de trabalho técnico, científico ou artístico, cujo critério de julgamento será o de melhor técnica ou conteúdo artístico, e para concessão de prêmio ou remuneração ao vencedor;","XL - leilão: modalidade de licitação para alienação de bens imóveis ou de bens móveis inservíveis ou legalmente apreendidos a quem oferecer o maior lance;","XLI - pregão: modalidade de licitação obrigatória para aquisição de bens e serviços comuns, cujo critério de julgamento poderá ser o de menor preço ou o de maior desconto;","XLII - diálogo competitivo: modalidade de licitação para contratação de obras, serviços e compras em que a Administração Pública realiza diálogos com licitantes previamente selecionados mediante critérios objetivos, com o intuito de desenvolver uma ou mais alternativas capazes de atender às suas necessidades, devendo os licitantes apresentar proposta final após o encerramento dos diálogos;","XLIII - credenciamento: processo administrativo de chamamento público em que a Administração Pública convoca interessados em prestar serviços ou fornecer bens para que, preenchidos os requisitos necessários, se credenciem no órgão ou na entidade para executar o objeto quando convocados;","XLIV - pré-qualificação: procedimento seletivo prévio à licitação, convocado por meio de edital, destinado à análise das condições de habilitação, total ou parcial, dos interessados ou do objeto;","XLV - sistema de registro de preços: conjunto de procedimentos para realização, mediante contratação direta ou licitação nas modalidades pregão ou concorrência, de registro formal de preços relativos a prestação de serviços, a obras e a aquisição e locação de bens para contratações futuras;","XLVI - ata de registro de preços: documento vinculativo e obrigacional, com característica de compromisso para futura contratação, no qual são registrados o objeto, os preços, os fornecedores, os órgãos participantes e as condições a serem praticadas, conforme as disposições contidas no edital da licitação, no aviso ou instrumento de contratação direta e nas propostas apresentadas;","XLVII - órgão ou entidade gerenciadora: órgão ou entidade da Administração Pública responsável pela condução do conjunto de procedimentos para registro de preços e pelo gerenciamento da ata de registro de preços dele decorrente;","XLVIII - órgão ou entidade participante: órgão ou entidade da Administração Pública que participa dos procedimentos iniciais da contratação para registro de preços e integra a ata de registro de preços;","XLIX - órgão ou entidade não participante: órgão ou entidade da Administração Pública que não participa dos procedimentos iniciais da licitação para registro de preços e não integra a ata de registro de preços;","L - comissão de contratação: conjunto de agentes públicos indicados pela Administração, em caráter permanente ou especial, com a função de receber, examinar e julgar documentos relativos às licitações e aos procedimentos auxiliares;","LI - catálogo eletrônico de padronização de compras, serviços e obras: sistema informatizado, de gerenciamento centralizado e com indicação de preços, destinado a permitir a padronização de itens a serem adquiridos pela Administração Pública e que estarão disponíveis para a licitação;","LII - sítio eletrônico oficial: sítio da internet, certificado digitalmente por autoridade certificadora, no qual o ente federativo divulga de forma centralizada as informações e os serviços de governo digital dos seus órgãos e entidades;","LIII - contrato de eficiência: contrato cujo objeto é a prestação de serviços, que pode incluir a realização de obras e o fornecimento de bens, com o objetivo de proporcionar economia ao contratante, na forma de redução de despesas correntes, remunerado o contratado com base em percentual da economia gerada;","LIV - seguro-garantia: seguro que garante o fiel cumprimento das obrigações assumidas pelo contratado;","LV - produtos para pesquisa e desenvolvimento: bens, insumos, serviços e obras necessários para atividade de pesquisa científica e tecnológica, desenvolvimento de tecnologia ou inovação tecnológica, discriminados em projeto de pesquisa;","LVI - sobrepreço: preço orçado para licitação ou contratado em valor expressivamente superior aos preços referenciais de mercado, seja de apenas 1 (um) item, se a licitação ou a contratação for por preços unitários de serviço, seja do valor global do objeto, se a licitação ou a contratação for por tarefa, empreitada por preço global ou empreitada integral, semi-integrada ou integrada;","LVII - superfaturamento: dano provocado ao patrimônio da Administração, caracterizado, entre outras situações, por:","a) medição de quantidades superiores às efetivamente executadas ou fornecidas;","b) deficiência na execução de obras e de serviços de engenharia que resulte em diminuição da sua qualidade, vida útil ou segurança;","c) alterações no orçamento de obras e de serviços de engenharia que causem desequilíbrio econômico-financeiro do contrato em favor do contratado;","d) outras alterações de cláusulas financeiras que gerem recebimentos contratuais antecipados, distorção do cronograma físico-financeiro, prorrogação injustificada do prazo contratual com custos adicionais para a Administração ou reajuste irregular de preços;","LVIII - reajustamento em sentido estrito: forma de manutenção do equilíbrio econômico-financeiro de contrato consistente na aplicação do índice de correção monetária previsto no contrato, que deve retratar a variação efetiva do custo de produção, admitida a adoção de índices específicos ou setoriais;","LIX - repactuação: forma de manutenção do equilíbrio econômico-financeiro de contrato utilizada para serviços contínuos com regime de dedicação exclusiva de mão de obra ou predominância de mão de obra, por meio da análise da variação dos custos contratuais, devendo estar prevista no edital com data vinculada à apresentação das propostas, para os custos decorrentes do mercado, e com data vinculada ao acordo, à convenção coletiva ou ao dissídio coletivo ao qual o orçamento esteja vinculado, para os custos decorrentes da mão de obra;","LX - agente de contratação: pessoa designada pela autoridade competente, entre servidores efetivos ou empregados públicos dos quadros permanentes da Administração Pública, para tomar decisões, acompanhar o trâmite da licitação, dar impulso ao procedimento licitatório e executar quaisquer outras atividades necessárias ao bom andamento do certame até a homologação."],"url":""},{"key":"l14133:178","law":"l14133","ref":"178","label":"Nova Lei de Licitações e Contratos · Art. 178","paragraphs":["Art. 178. O Título XI da Parte Especial do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), passa a vigorar acrescido do seguinte Capítulo II-B:","\"CAPÍTULO II-B","DOS CRIMES EM LICITAÇÕES E CONTRATOS ADMINISTRATIVOS","Contratação direta ilegal"],"url":""},{"key":"l14133:3","law":"l14133","ref":"3","label":"Nova Lei de Licitações e Contratos · Art. 3","paragraphs":["Art. 3º Não se subordinam ao regime desta Lei:","I - contratos que tenham por objeto operação de crédito, interno ou externo, e gestão de dívida pública, incluídas as contratações de agente financeiro e a concessão de garantia relacionadas a esses contratos;","II - contratações sujeitas a normas previstas em legislação própria."],"url":""},{"key":"l14133:42","law":"l14133","ref":"42","label":"Nova Lei de Licitações e Contratos · Art. 42","paragraphs":["Art. 42. A prova de qualidade de produto apresentado pelos proponentes como similar ao das marcas eventualmente indicadas no edital será admitida por qualquer um dos seguintes meios:","I - comprovação de que o produto está de acordo com as normas técnicas determinadas pelos órgãos oficiais competentes, pela Associação Brasileira de Normas Técnicas (ABNT) ou por outra entidade credenciada pelo Inmetro;","II - declaração de atendimento satisfatório emitida por outro órgão ou entidade de nível federativo equivalente ou superior que tenha adquirido o produto;","III - certificação, certificado, laudo laboratorial ou documento similar que possibilite a aferição da qualidade e da conformidade do produto ou do processo de fabricação, inclusive sob o aspecto ambiental, emitido por instituição oficial competente ou por entidade credenciada.","§ 1º O edital poderá exigir, como condição de aceitabilidade da proposta, certificação de qualidade do produto por instituição credenciada pelo Conselho Nacional de Metrologia, Normalização e Qualidade Industrial (Conmetro).","§ 2º A Administração poderá, nos termos do edital de licitação, oferecer protótipo do objeto pretendido e exigir, na fase de julgamento das propostas, amostras do licitante provisoriamente vencedor, para atender a diligência ou, após o julgamento, como condição para firmar contrato.","§ 3º No interesse da Administração, as amostras a que se refere o § 2º deste artigo poderão ser examinadas por instituição com reputação ético-profissional na especialidade do objeto, previamente indicada no edital."],"url":""},{"key":"l14133:49","law":"l14133","ref":"49","label":"Nova Lei de Licitações e Contratos · Art. 49","paragraphs":["Art. 49. A Administração poderá, mediante justificativa expressa, contratar mais de uma empresa ou instituição para executar o mesmo serviço, desde que essa contratação não implique perda de economia de escala, quando:","I - o objeto da contratação puder ser executado de forma concorrente e simultânea por mais de um contratado; e","II - a múltipla execução for conveniente para atender à Administração.","Parágrafo único. Na hipótese prevista no caput deste artigo, a Administração deverá manter o controle individualizado da execução do objeto contratual relativamente a cada um dos contratados."],"url":""},{"key":"l14133:43","law":"l14133","ref":"43","label":"Nova Lei de Licitações e Contratos · Art. 43","paragraphs":["Art. 43. O processo de padronização deverá conter:","I - parecer técnico sobre o produto, considerados especificações técnicas e estéticas, desempenho, análise de contratações anteriores, custo e condições de manutenção e garantia;","II - despacho motivado da autoridade superior, com a adoção do padrão;","III - síntese da justificativa e descrição sucinta do padrão definido, divulgadas em sítio eletrônico oficial.","§ 1º É permitida a padronização com base em processo de outro órgão ou entidade de nível federativo igual ou superior ao do órgão adquirente, devendo o ato que decidir pela adesão a outra padronização ser devidamente motivado, com indicação da necessidade da Administração e dos riscos decorrentes dessa decisão, e divulgado em sítio eletrônico oficial.","§ 2º As contratações de soluções baseadas em software de uso disseminado serão disciplinadas em regulamento que defina processo de gestão estratégica das contratações desse tipo de solução."],"url":""},{"key":"l14133:44","law":"l14133","ref":"44","label":"Nova Lei de Licitações e Contratos · Art. 44","paragraphs":["Art. 44. Quando houver a possibilidade de compra ou de locação de bens, o estudo técnico preliminar deverá considerar os custos e os benefícios de cada opção, com indicação da alternativa mais vantajosa."],"url":""},{"key":"l14133:44-A","law":"l14133","ref":"44-A","label":"Nova Lei de Licitações e Contratos · Art. 44-A","paragraphs":["Art. 44-A. O processo licitatório para compra de equipamento destinado a procedimento diagnóstico ou terapêutico no âmbito do Sistema Único de Saúde (SUS) que tenha valor superior ao previsto no inciso II do art. 75 desta Lei deve levar em consideração o seu adequado aproveitamento ao longo de sua vida útil. (“Caput” do artigo acrescido pela Lei nº 15.210, de 16/9/2025, publicada no DOU de 17/9/2025, em vigor 180 dias após a publicação)","§ 1º No edital de licitação, deve constar a demonstração da capacidade instalada para operação do equipamento ou o plano de atendimento aos requisitos necessários à operação. (Parágrafo acrescido pela Lei nº 15.210, de 16/9/2025, publicada no DOU de 17/9/2025, em vigor 180 dias após a publicação)","§ 2º (VETADO na Lei nº 15.210, de 16/9/2025, publicada no DOU de 17/9/2025, em vigor 180 dias após a publicação)","§ 3º (VETADO na Lei nº 15.210, de 16/9/2025, publicada no DOU de 17/9/2025, em vigor 180 dias após a publicação)","§ 4º (VETADO na Lei nº 15.210, de 16/9/2025, publicada no DOU de 17/9/2025, em vigor 180 dias após a publicação)","§ 5º (VETADO na Lei nº 15.210, de 16/9/2025, publicada no DOU de 17/9/2025, em vigor 180 dias após a publicação)"],"url":""},{"key":"l14133:45","law":"l14133","ref":"45","label":"Nova Lei de Licitações e Contratos · Art. 45","paragraphs":["Art. 45. As licitações de obras e serviços de engenharia devem respeitar, especialmente, as normas relativas a:","I - disposição final ambientalmente adequada dos resíduos sólidos gerados pelas obras contratadas;","II - mitigação por condicionantes e compensação ambiental, que serão definidas no procedimento de licenciamento ambiental;","III - utilização de produtos, de equipamentos e de serviços que, comprovadamente, favoreçam a redução do consumo de energia e de recursos naturais;","IV - avaliação de impacto de vizinhança, na forma da legislação urbanística;","V - proteção do patrimônio histórico, cultural, arqueológico e imaterial, inclusive por meio da avaliação do impacto direto ou indireto causado pelas obras contratadas;","VI - acessibilidade para pessoas com deficiência ou com mobilidade reduzida."],"url":""},{"key":"l14133:46","law":"l14133","ref":"46","label":"Nova Lei de Licitações e Contratos · Art. 46","paragraphs":["Art. 46. Na execução indireta de obras e serviços de engenharia, são admitidos os seguintes regimes:","I - empreitada por preço unitário;","II - empreitada por preço global;","III - empreitada integral;","IV - contratação por tarefa;","V - contratação integrada;","VI - contratação semi-integrada;","VII - fornecimento e prestação de serviço associado.","§ 1º É vedada a realização de obras e serviços de engenharia sem projeto executivo, ressalvada a hipótese prevista no § 3º do art. 18 desta Lei.","§ 2º A Administração é dispensada da elaboração de projeto básico nos casos de contratação integrada, hipótese em que deverá ser elaborado anteprojeto de acordo com metodologia definida em ato do órgão competente, observados os requisitos estabelecidos no inciso XXIV do art. 6º desta Lei.","§ 3º Na contratação integrada, após a elaboração do projeto básico pelo contratado, o conjunto de desenhos, especificações, memoriais e cronograma físico-financeiro deverá ser submetido à aprovação da Administração, que avaliará sua adequação em relação aos parâmetros definidos no edital e conformidade com as normas técnicas, vedadas alterações que reduzam a qualidade ou a vida útil do empreendimento e mantida a responsabilidade integral do contratado pelos riscos associados ao projeto básico.","§ 4º Nos regimes de contratação integrada e semi-integrada, o edital e o contrato, sempre que for o caso, deverão prever as providências necessárias para a efetivação de desapropriação autorizada pelo poder público, bem como:","I - o responsável por cada fase do procedimento expropriatório;","II - a responsabilidade pelo pagamento das indenizações devidas;","III - a estimativa do valor a ser pago a título de indenização pelos bens expropriados, inclusive de custos correlatos;","IV - a distribuição objetiva de riscos entre as partes, incluído o risco pela diferença entre o custo da desapropriação e a estimativa de valor e pelos eventuais danos e prejuízos ocasionados por atraso na disponibilização dos bens expropriados;","V - em nome de quem deverá ser promovido o registro de imissão provisória na posse e o registro de propriedade dos bens a serem desapropriados.","§ 5º Na contratação semi-integrada, mediante prévia autorização da Administração, o projeto básico poderá ser alterado, desde que demonstrada a superioridade das inovações propostas pelo contratado em termos de redução de custos, de aumento da qualidade, de redução do prazo de execução ou de facilidade de manutenção ou operação, assumindo o contratado a responsabilidade integral pelos riscos associados à alteração do projeto básico.","§ 6º A execução de cada etapa será obrigatoriamente precedida da conclusão e da aprovação, pela autoridade competente, dos trabalhos relativos às etapas anteriores.","§ 7º (VETADO).","§ 8º (VETADO).","§ 9º Os regimes de execução a que se referem os incisos II, III, IV, V e VI do caput deste artigo serão licitados por preço global e adotarão sistemática de medição e pagamento associada à execução de etapas do cronograma físico-financeiro vinculadas ao cumprimento de metas de resultado, vedada a adoção de sistemática de remuneração orientada por preços unitários ou referenciada pela execução de quantidades de itens unitários."],"url":""},{"key":"l14133:47","law":"l14133","ref":"47","label":"Nova Lei de Licitações e Contratos · Art. 47","paragraphs":["Art. 47. As licitações de serviços atenderão aos princípios:","I - da padronização, considerada a compatibilidade de especificações estéticas, técnicas ou de desempenho;","II - do parcelamento, quando for tecnicamente viável e economicamente vantajoso.","§ 1º Na aplicação do princípio do parcelamento deverão ser considerados:","I - a responsabilidade técnica;","II - o custo para a Administração de vários contratos frente às vantagens da redução de custos, com divisão do objeto em itens;","III - o dever de buscar a ampliação da competição e de evitar a concentração de mercado.","§ 2º Na licitação de serviços de manutenção e assistência técnica, o edital deverá definir o local de realização dos serviços, admitida a exigência de deslocamento de técnico ao local da repartição ou a exigência de que o contratado tenha unidade de prestação de serviços em distância compatível com as necessidades da Administração."],"url":""},{"key":"l14133:48","law":"l14133","ref":"48","label":"Nova Lei de Licitações e Contratos · Art. 48","paragraphs":["Art. 48. Poderão ser objeto de execução por terceiros as atividades materiais acessórias, instrumentais ou complementares aos assuntos que constituam área de competência legal do órgão ou da entidade, vedado à Administração ou a seus agentes, na contratação do serviço terceirizado:","I - indicar pessoas expressamente nominadas para executar direta ou indiretamente o objeto contratado;","II - fixar salário inferior ao definido em lei ou em ato normativo a ser pago pelo contratado;","III - estabelecer vínculo de subordinação com funcionário de empresa prestadora de serviço terceirizado;","IV - definir forma de pagamento mediante exclusivo reembolso dos salários pagos;","V - demandar a funcionário de empresa prestadora de serviço terceirizado a execução de tarefas fora do escopo do objeto da contratação;","VI - prever em edital exigências que constituam intervenção indevida da Administração na gestão interna do contratado.","Parágrafo único. Durante a vigência do contrato, é vedado ao contratado contratar cônjuge, companheiro ou parente em linha reta, colateral ou por afinidade, até o terceiro grau, de dirigente do órgão ou entidade contratante ou de agente público que desempenhe função na licitação ou atue na fiscalização ou na gestão do contrato, devendo essa proibição constar expressamente do edital de licitação."],"url":""},{"key":"l14133:4","law":"l14133","ref":"4","label":"Nova Lei de Licitações e Contratos · Art. 4","paragraphs":["Art. 4º Aplicam-se às licitações e contratos disciplinados por esta Lei as disposições constantes dos arts. 42 a 49 da Lei Complementar nº 123, de 14 de dezembro de 2006.","§ 1º As disposições a que se refere o caput deste artigo não são aplicadas:","I - no caso de licitação para aquisição de bens ou contratação de serviços em geral, ao item cujo valor estimado for superior à receita bruta máxima admitida para fins de enquadramento como empresa de pequeno porte;","II - no caso de contratação de obras e serviços de engenharia, às licitações cujo valor estimado for superior à receita bruta máxima admitida para fins de enquadramento como empresa de pequeno porte.","§ 2º A obtenção de benefícios a que se refere o caput deste artigo fica limitada às microempresas e às empresas de pequeno porte que, no ano-calendário de realização da licitação, ainda não tenham celebrado contratos com a Administração Pública cujos valores somados extrapolem a receita bruta máxima admitida para fins de enquadramento como empresa de pequeno porte, devendo o órgão ou entidade exigir do licitante declaração de observância desse limite na licitação.","§ 3º Nas contratações com prazo de vigência superior a 1 (um) ano, será considerado o valor anual do contrato na aplicação dos limites previstos nos §§ 1º e 2º deste artigo."],"url":""},{"key":"l14133:28","law":"l14133","ref":"28","label":"Nova Lei de Licitações e Contratos · Art. 28","paragraphs":["Art. 28. São modalidades de licitação:","I - pregão;","II - concorrência;","III - concurso;","IV - leilão;","V - diálogo competitivo.","§ 1º Além das modalidades referidas no caput deste artigo, a Administração pode servir-se dos procedimentos auxiliares previstos no art. 78 desta Lei.","§ 2º É vedada a criação de outras modalidades de licitação ou, ainda, a combinação daquelas referidas no caput deste artigo."],"url":""},{"key":"lindb:20","law":"lindb","ref":"20","label":"LINDB · LINDB · Art. 20","paragraphs":["Art. 20. Nas esferas administrativa, controladora e judicial, não se decidirá com base em valores jurídicos abstratos sem que sejam consideradas as consequências práticas da decisão.","Parágrafo único. A motivação demonstrará a necessidade e a adequação da medida imposta ou da invalidação de ato, contrato, ajuste, processo ou norma administrativa, inclusive em face das possíveis alternativas. (Artigo acrescido pela Lei nº 13.655, de 25/4/2018)"],"url":""},{"key":"lindb:22","law":"lindb","ref":"22","label":"LINDB · LINDB · Art. 22","paragraphs":["Art. 22. Na interpretação de normas sobre gestão pública, serão considerados os obstáculos e as dificuldades reais do gestor e as exigências das políticas públicas a seu cargo, sem prejuízo dos direitos dos administrados.","§ 1º Em decisão sobre regularidade de conduta ou validade de ato, contrato, ajuste, processo ou norma administrativa, serão consideradas as circunstâncias práticas que houverem imposto, limitado ou condicionado a ação do agente.","§ 2º Na aplicação de sanções, serão consideradas a natureza e a gravidade da infração cometida, os danos que dela provierem para a administração pública, as circunstâncias agravantes ou atenuantes e os antecedentes do agente.","§ 3º As sanções aplicadas ao agente serão levadas em conta na dosimetria das demais sanções de mesma natureza e relativas ao mesmo fato. (Artigo acrescido pela Lei nº 13.655, de 25/4/2018)"],"url":""},{"key":"lindb:23","law":"lindb","ref":"23","label":"LINDB · LINDB · Art. 23","paragraphs":["Art. 23. A decisão administrativa, controladora ou judicial que estabelecer interpretação ou orientação nova sobre norma de conteúdo indeterminado, impondo novo dever ou novo condicionamento de direito, deverá prever regime de transição quando indispensável para que o novo dever ou condicionamento de direito seja cumprido de modo proporcional, equânime e eficiente e sem prejuízo aos interesses gerais.","Parágrafo único. (VETADO). (Artigo acrescido pela Lei nº 13.655, de 25/4/2018)"],"url":""},{"key":"lindb:24","law":"lindb","ref":"24","label":"LINDB · LINDB · Art. 24","paragraphs":["Art. 24. A revisão, nas esferas administrativa, controladora ou judicial, quanto à validade de ato, contrato, ajuste, processo ou norma administrativa cuja produção já se houver completado levará em conta as orientações gerais da época, sendo vedado que, com base em mudança posterior de orientação geral, se declarem inválidas situações plenamente constituídas.","Parágrafo único. Consideram-se orientações gerais as interpretações e especificações contidas em atos públicos de caráter geral ou em jurisprudência judicial ou administrativa majoritária, e ainda as adotadas por prática administrativa reiterada e de amplo conhecimento público. (Artigo acrescido pela Lei nº 13.655, de 25/4/2018)"],"url":""},{"key":"l14133:7","law":"l14133","ref":"7","label":"Nova Lei de Licitações e Contratos · Art. 7","paragraphs":["Art. 7º Caberá à autoridade máxima do órgão ou da entidade, ou a quem as normas de organização administrativa indicarem, promover gestão por competências e designar agentes públicos para o desempenho das funções essenciais à execução desta Lei que preencham os seguintes requisitos:","I - sejam, preferencialmente, servidor efetivo ou empregado público dos quadros permanentes da Administração Pública;","II - tenham atribuições relacionadas a licitações e contratos ou possuam formação compatível ou qualificação atestada por certificação profissional emitida por escola de governo criada e mantida pelo poder público; e","III - não sejam cônjuge ou companheiro de licitantes ou contratados habituais da Administração nem tenham com eles vínculo de parentesco, colateral ou por afinidade, até o terceiro grau, ou de natureza técnica, comercial, econômica, financeira, trabalhista e civil.","§ 1º A autoridade referida no caput deste artigo deverá observar o princípio da segregação de funções, vedada a designação do mesmo agente público para atuação simultânea em funções mais suscetíveis a riscos, de modo a reduzir a possibilidade de ocultação de erros e de ocorrência de fraudes na respectiva contratação.","§ 2º O disposto no caput e no § 1º deste artigo, inclusive os requisitos estabelecidos, também se aplica aos órgãos de assessoramento jurídico e de controle interno da Administração."],"url":""},{"key":"l14133:10","law":"l14133","ref":"10","label":"Nova Lei de Licitações e Contratos · Art. 10","paragraphs":["Art. 10. Se as autoridades competentes e os servidores públicos que tiverem participado dos procedimentos relacionados às licitações e aos contratos de que trata esta Lei precisarem defender-se nas esferas administrativa, controladora ou judicial em razão de ato praticado com estrita observância de orientação constante em parecer jurídico elaborado na forma do § 1º do art. 53 desta Lei, a advocacia pública promoverá, a critério do agente público, sua representação judicial ou extrajudicial.","§ 1º Não se aplica o disposto no caput deste artigo quando:","I - (VETADO);","II - provas da prática de atos ilícitos dolosos constarem nos autos do processo administrativo ou judicial.","§ 2º Aplica-se o disposto no caput deste artigo inclusive na hipótese de o agente público não mais ocupar o cargo, emprego ou função em que foi praticado o ato questionado."],"url":""},{"key":"l14133:8","law":"l14133","ref":"8","label":"Nova Lei de Licitações e Contratos · Art. 8","paragraphs":["Art. 8º A licitação será conduzida por agente de contratação, pessoa designada pela autoridade competente, entre servidores efetivos ou empregados públicos dos quadros permanentes da Administração Pública, para tomar decisões, acompanhar o trâmite da licitação, dar impulso ao procedimento licitatório e executar quaisquer outras atividades necessárias ao bom andamento do certame até a homologação.","§ 1º O agente de contratação será auxiliado por equipe de apoio e responderá individualmente pelos atos que praticar, salvo quando induzido a erro pela atuação da equipe.","§ 2º Em licitação que envolva bens ou serviços especiais, desde que observados os requisitos estabelecidos no art. 7º desta Lei, o agente de contratação poderá ser substituído por comissão de contratação formada por, no mínimo, 3 (três) membros, que responderão solidariamente por todos os atos praticados pela comissão, ressalvado o membro que expressar posição individual divergente fundamentada e registrada em ata lavrada na reunião em que houver sido tomada a decisão.","§ 3º As regras relativas à atuação do agente de contratação e da equipe de apoio, ao funcionamento da comissão de contratação e à atuação de fiscais e gestores de contratos de que trata esta Lei serão estabelecidas em regulamento, e deverá ser prevista a possibilidade de eles contarem com o apoio dos órgãos de assessoramento jurídico e de controle interno para o desempenho das funções essenciais à execução do disposto nesta Lei.","§ 4º Em licitação que envolva bens ou serviços especiais cujo objeto não seja rotineiramente contratado pela Administração, poderá ser contratado, por prazo determinado, serviço de empresa ou de profissional especializado para assessorar os agentes públicos responsáveis pela condução da licitação.","§ 5º Em licitação na modalidade pregão, o agente responsável pela condução do certame será designado pregoeiro."],"url":""},{"key":"l14133:9","law":"l14133","ref":"9","label":"Nova Lei de Licitações e Contratos · Art. 9","paragraphs":["Art. 9º É vedado ao agente público designado para atuar na área de licitações e contratos, ressalvados os casos previstos em lei:","I - admitir, prever, incluir ou tolerar, nos atos que praticar, situações que:","a) comprometam, restrinjam ou frustrem o caráter competitivo do processo licitatório, inclusive nos casos de participação de sociedades cooperativas;","b) estabeleçam preferências ou distinções em razão da naturalidade, da sede ou do domicílio dos licitantes;","c) sejam impertinentes ou irrelevantes para o objeto específico do contrato;","II - estabelecer tratamento diferenciado de natureza comercial, legal, trabalhista, previdenciária ou qualquer outra entre empresas brasileiras e estrangeiras, inclusive no que se refere a moeda, modalidade e local de pagamento, mesmo quando envolvido financiamento de agência internacional;","III - opor resistência injustificada ao andamento dos processos e, indevidamente, retardar ou deixar de praticar ato de ofício, ou praticá-lo contra disposição expressa em lei.","§ 1º Não poderá participar, direta ou indiretamente, da licitação ou da execução do contrato agente público de órgão ou entidade licitante ou contratante, devendo ser observadas as situações que possam configurar conflito de interesses no exercício ou após o exercício do cargo ou emprego, nos termos da legislação que disciplina a matéria.","§ 2º As vedações de que trata este artigo estendem-se a terceiro que auxilie a condução da contratação na qualidade de integrante de equipe de apoio, profissional especializado ou funcionário ou representante de empresa que preste assessoria técnica."],"url":""},{"key":"l14133:174","law":"l14133","ref":"174","label":"Nova Lei de Licitações e Contratos · Art. 174","paragraphs":["Art. 174. É criado o Portal Nacional de Contratações Públicas (PNCP), sítio eletrônico oficial destinado à:","I - divulgação centralizada e obrigatória dos atos exigidos por esta Lei;","II - realização facultativa das contratações pelos órgãos e entidades dos Poderes Executivo, Legislativo e Judiciário de todos os entes federativos.","§ 1º O PNCP será gerido pelo Comitê Gestor da Rede Nacional de Contratações Públicas, a ser presidido por representante indicado pelo Presidente da República e composto de:","I - 3 (três) representantes da União indicados pelo Presidente da República;","II - 2 (dois) representantes dos Estados e do Distrito Federal indicados pelo Conselho Nacional de Secretários de Estado da Administração;","III - 2 (dois) representantes dos Municípios indicados pela Confederação Nacional de Municípios.","§ 2º O PNCP conterá, entre outras, as seguintes informações acerca das contratações:","I - planos de contratação anuais;","II - catálogos eletrônicos de padronização;","III - editais de credenciamento e de pré-qualificação, avisos de contratação direta e editais de licitação e respectivos anexos;","IV - atas de registro de preços;","V - contratos e termos aditivos;","VI - notas fiscais eletrônicas, quando for o caso.","§ 3º O PNCP deverá, entre outras funcionalidades, oferecer:","I - sistema de registro cadastral unificado;","II - painel para consulta de preços, banco de preços em saúde e acesso à base nacional de notas fiscais eletrônicas;","III - sistema de planejamento e gerenciamento de contratações, incluído o cadastro de atesto de cumprimento de obrigações previsto no § 4º do art. 88 desta Lei;","IV - sistema eletrônico para a realização de sessões públicas;","V - acesso ao Cadastro Nacional de Empresas Inidôneas e Suspensas (Ceis) e ao Cadastro Nacional de Empresas Punidas (Cnep);","VI - sistema de gestão compartilhada com a sociedade de informações referentes à execução do contrato, que possibilite:","a) envio, registro, armazenamento e divulgação de mensagens de texto ou imagens pelo interessado previamente identificado;","b) acesso ao sistema informatizado de acompanhamento de obras a que se refere o inciso III do caput do art. 19 desta Lei;","c) comunicação entre a população e representantes da Administração e do contratado designados para prestar as informações e esclarecimentos pertinentes, na forma de regulamento;","d) divulgação, na forma de regulamento, de relatório final com informações sobre a consecução dos objetivos que tenham justificado a contratação e eventuais condutas a serem adotadas para o aprimoramento das atividades da Administração.","VII - o Sicx. (Inciso acrescido pela Lei nº 15.266, de 21/11/2025)","§ 3º-A. As funcionalidades a que se refere o § 3º deste artigo serão os sistemas adotados e oferecidos pelo Poder Executivo federal. (Parágrafo acrescido pela Lei nº 15.266, de 21/11/2025)","§ 4º O PNCP adotará o formato de dados abertos e observará as exigências previstas na Lei nº 12.527, de 18 de novembro de 2011.","§ 5º (VETADO)."],"url":""},{"key":"l14133:78","law":"l14133","ref":"78","label":"Nova Lei de Licitações e Contratos · Art. 78","paragraphs":["Art. 78. São procedimentos auxiliares das licitações e das contratações regidas por esta Lei:","I - credenciamento;","II - pré-qualificação;","III - procedimento de manifestação de interesse;","IV - sistema de registro de preços;","V - registro cadastral.","§ 1º Os procedimentos auxiliares de que trata o caput deste artigo obedecerão a critérios claros e objetivos definidos em regulamento.","§ 2º O julgamento que decorrer dos procedimentos auxiliares das licitações previstos nos incisos II e III do caput deste artigo seguirá o mesmo procedimento das licitações."],"url":""},{"key":"l14133:81","law":"l14133","ref":"81","label":"Nova Lei de Licitações e Contratos · Art. 81","paragraphs":["Art. 81. A Administração poderá solicitar à iniciativa privada, mediante procedimento aberto de manifestação de interesse a ser iniciado com a publicação de edital de chamamento público, a propositura e a realização de estudos, investigações, levantamentos e projetos de soluções inovadoras que contribuam com questões de relevância pública, na forma de regulamento.","§ 1º Os estudos, as investigações, os levantamentos e os projetos vinculados à contratação e de utilidade para a licitação, realizados pela Administração ou com a sua autorização, estarão à disposição dos interessados, e o vencedor da licitação deverá ressarcir os dispêndios correspondentes, conforme especificado no edital.","§ 2º A realização, pela iniciativa privada, de estudos, investigações, levantamentos e projetos em decorrência do procedimento de manifestação de interesse previsto no caput deste artigo:","I - não atribuirá ao realizador direito de preferência no processo licitatório;","II - não obrigará o poder público a realizar licitação;","III - não implicará, por si só, direito a ressarcimento de valores envolvidos em sua elaboração;","IV - será remunerada somente pelo vencedor da licitação, vedada, em qualquer hipótese, a cobrança de valores do poder público.","§ 3º Para aceitação dos produtos e serviços de que trata o caput deste artigo, a Administração deverá elaborar parecer fundamentado com a demonstração de que o produto ou serviço entregue é adequado e suficiente à compreensão do objeto, de que as premissas adotadas são compatíveis com as reais necessidades do órgão e de que a metodologia proposta é a que propicia maior economia e vantagem entre as demais possíveis.","§ 4º O procedimento previsto no caput deste artigo poderá ser restrito a startups, assim considerados os microempreendedores individuais, as microempresas e as empresas de pequeno porte, de natureza emergente e com grande potencial, que se dediquem à pesquisa, ao desenvolvimento e à implementação de novos produtos ou serviços baseados em soluções tecnológicas inovadoras que possam causar alto impacto, exigida, na seleção definitiva da inovação, validação prévia fundamentada em métricas objetivas, de modo a demonstrar o atendimento das necessidades da Administração."],"url":""},{"key":"lindb:21","law":"lindb","ref":"21","label":"LINDB · LINDB · Art. 21","paragraphs":["Art. 21. A decisão que, nas esferas administrativa, controladora ou judicial, decretar a invalidação de ato, contrato, ajuste, processo ou norma administrativa deverá indicar de modo expresso suas consequências jurídicas e administrativas.","Parágrafo único. A decisão a que se refere o caput deste artigo deverá, quando for o caso, indicar as condições para que a regularização ocorra de modo proporcional e equânime e sem prejuízo aos interesses gerais, não se podendo impor aos sujeitos atingidos ônus ou perdas que, em função das peculiaridades do caso, sejam anormais ou excessivos. (Artigo acrescido pela Lei nº 13.655, de 25/4/2018)"],"url":""},{"key":"lindb:28","law":"lindb","ref":"28","label":"LINDB · LINDB · Art. 28","paragraphs":["Art. 28. O agente público responderá pessoalmente por suas decisões ou opiniões técnicas em caso de dolo ou erro grosseiro.","§ 1º (VETADO).","§ 2º (VETADO).","§ 3º (VETADO). (Artigo acrescido pela Lei nº 13.655, de 25/4/2018)"],"url":""},{"key":"l13303:28","law":"l13303","ref":"28","label":"Lei das Estatais · Art. 28","paragraphs":["Art. 28. Os contratos com terceiros destinados à prestação de serviços às empresas públicas e às sociedades de economia mista, inclusive de engenharia e de publicidade, à aquisição e à locação de bens, à alienação de bens e ativos integrantes do respectivo patrimônio ou à execução de obras a serem integradas a esse patrimônio, bem como à implementação de ônus real sobre tais bens, serão precedidos de licitação nos termos desta Lei, ressalvadas as hipóteses previstas nos arts. 29 e 30.","§ 1º Aplicam-se às licitações das empresas públicas e das sociedades de economia mista as disposições constantes dos arts. 42 a 49 da Lei Complementar nº 123, de 14 de dezembro de 2006.","§ 2º O convênio ou contrato de patrocínio celebrado com pessoas físicas ou jurídicas de que trata o § 3º do art. 27 observará, no que couber, as normas de licitação e contratos desta Lei.","§ 3º São as empresas públicas e as sociedades de economia mista dispensadas da observância dos dispositivos deste Capítulo nas seguintes situações:","I - comercialização, prestação ou execução, de forma direta, pelas empresas mencionadas no caput , de produtos, serviços ou obras especificamente relacionados com seus respectivos objetos sociais;","II - nos casos em que a escolha do parceiro esteja associada a suas características particulares, vinculada a oportunidades de negócio definidas e específicas, justificada a inviabilidade de procedimento competitivo.","§ 4º Consideram-se oportunidades de negócio a que se refere o inciso II do § 3º a formação e a extinção de parcerias e outras formas associativas, societárias ou contratuais, a aquisição e a alienação de participação em sociedades e outras formas associativas, societárias ou contratuais e as operações realizadas no âmbito do mercado de capitais, respeitada a regulação pelo respectivo órgão competente."],"url":""}];})(window);
